/// </summary>
[ExtensionOf(classStr(SalesLineSplitReturnLine))]
internal final class AVASalesLineSplitReturnLineCls_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>initSplitLine</c> method.
/// </summary>
/// <param name="_origLine">
///     <c>SalesLine</c> as type
/// </param>
/// <param name="_newExpectedRetQty">
///     <c>SalesQty</c> as type
/// </param>
/// <param name="_newCWQty">
///     <c>PdsCWInventQty</c> as type
/// </param>
/// <returns>
///     <c>SalesLine</c> as return value
/// </returns>
protected SalesLine initSplitLine(SalesLine _origLine, SalesQty _newExpectedRetQty, PdsCWInventQty _newCWQty)
{
    SalesLine   locSalesLine;

    locSalesLine = next initSplitLine(_origLine,_newExpectedRetQty,_newCWQty);

    locSalesLine.AVADispositionCodeId = _origLine.AVADispositionCodeId;

    return locSalesLine;
}
